head.script:
// 이벤트 발생 순서 추적용
scwin.eventOrder = [];



scwin.tData = {
    "description" : "[multiselect > E > onrowclick]<br/>MultiSelect 컴포넌트의 아이템을 클릭했을 때 발생합니다.",
    "validation" : [
        "아이템을 클릭하여 선택값이 변경되면 'onviewchange → onrowclick' 순서로 이벤트가 발생합니다.",
        "oldValue 와 newValue 가 다를 때만 onviewchange 이벤트가 먼저 발생하며, 그 후에 onrowclick 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



// onviewchange — 선택값 변경 시 onrowclick 이전에 발생
scwin.target1_onviewchange = function (info) {
    scwin.eventOrder.push("onviewchange");
    wf_body_bottom.getObj("scwin").setReturnValue("===== target1 onviewchange =====");
};



scwin.target1_onrowclick = function (info) {
    scwin.eventOrder.push("onrowclick");
    wf_body_bottom.getObj("scwin").setReturnValue("===== target1 onrowclick =====");
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue: [" + (info ? info.oldValue : "") + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue: [" + (info ? info.newValue : "") + "]");
};



// comp 생성
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    scwin.eventOrder = [];

    let eList = $c.gcm.createEList(["onviewchange", "onrowclick"]);

    await $c.gcm.createBasicMultiSelect('', eList);
}
